test("牌堆：Deck 创建163个唯一实体 card.id", () => {
  const deck = new Deck(() => .4);
  assert.equal(deck.build(), 163);
  assert.equal(new Set(deck.cards.map((card) => card.id)).size, 163);
});

test("牌堆：结算区不会进入重洗", () => {
  const deck = new Deck(() => .4);
  deck.build();
  const resolving = deck.drawOne();
  const discard = deck.drawOne();
  deck.beginResolve(resolving);
  deck.discard(discard);
  deck.cards = [];
  deck.reshuffle();
  assert.equal(deck.cards.length, 1);
  assert.equal(deck.resolvingCards[0], resolving);
});

test("牌堆：判定区不会进入重洗", () => {
  const deck = new Deck(() => .4);
  deck.build();
  const judgment = deck.drawToJudgment();
  const discard = deck.drawOne();
  deck.discard(discard);
  deck.cards = [];
  deck.reshuffle();
  assert.equal(deck.cards.length, 1);
  assert.equal(deck.judgmentZone[0], judgment);
});

test("牌堆：重洗计数会准确累加", () => {
  const deck = new Deck();
  deck.discardPile.push(instance("charge"));
  deck.reshuffle();
  assert.equal(deck.reshuffleCount, 1);
});

// ---- 阵营与座位 ----

test("阵营：始终严格2V3", () => {
  for (let i = 0; i < 50; i += 1) {
    const teams = TeamManager.assignTeams(() => (i % 17) / 17);
    const dawn = teams.filter((t) => t === "dawn").length;
    const dusk = teams.filter((t) => t === "dusk").length;
    assert.deepEqual([dawn, dusk].sort(), [2, 3]);
  }
});

test("阵营：小队两名成员在环形座位上不相邻", () => {
  for (let i = 0; i < 40; i += 1) {
    const teams = TeamManager.assignTeams(() => (i % 19) / 19);
    const small = ["dawn", "dusk"].find((team) => teams.filter((entry) => entry === team).length === 2);
    const seats = teams.map((team, index) => team === small ? index : -1).filter((index) => index >= 0);
    const raw = Math.abs(seats[0] - seats[1]);
    assert.ok(Math.min(raw, 5 - raw) > 1);
  }
});

test("阵营：真人座位可以随机进入小队或大队", () => {
  const sizes = new Set();
  for (let i = 0; i < 60; i += 1) {
    const teams = TeamManager.assignTeams(() => ((i * 7) % 61) / 61);
    sizes.add(teams.filter((team) => team === teams[0]).length);
  }
  assert.deepEqual([...sizes].sort(), [2, 3]);
});

