test("调息：满生命角色即使持有调息也不能主动使用", () => {
  const { game, small, large }
    = makeTeamFixture();
  for (const player of [small, large]) {
    game.state.currentPlayerIndex = player.seatIndex;
    const recover = instance("recover");
    player.hand.push(recover);
    assert.equal(RuleEngine.canPlayCard(game, player, recover).ok, false);
  }
});

test("调息：二人小队可在同一出牌阶段连续使用多张调息", async () => {
  const { game, small }
    = makeTeamFixture();
  small.hp -= 2;
  small.hand.push(instance("recover"), instance("recover"));
  await game.playCard(small, small.hand[0], []);
  await game.playCard(small, small.hand[0], []);
  assert.equal(small.hp, small.maxHp);
  assert.equal(small.turnFlags.recoverUsed, 2);
  assert.equal(small.turnFlags.recoverLimit, null);
  assert.deepEqual(
    game.state.logs.filter((entry) => entry.message.includes("「调息」")).map((entry) => entry.message),
    [
      `${small.name}使用「调息」，恢复1点生命。`,
      `${small.name}使用「调息」，恢复1点生命。`
    ]
  );
  assert.ok(!game.state.logs.some((entry) => entry.message === `${small.name}恢复1点生命。`));
});

test("调息：三人小队可在同一出牌阶段连续使用多张调息", async () => {
  const { game, large }
    = makeTeamFixture();
  game.state.currentPlayerIndex = large.seatIndex;
  large.hp -= 2;
  large.hand.push(instance("recover"), instance("recover"));
  await game.playCard(large, large.hand[0], []);
  await game.playCard(large, large.hand[0], []);
  assert.equal(large.hp, large.maxHp);
  assert.equal(large.turnFlags.recoverUsed, 2);
  assert.equal(large.turnFlags.recoverLimit, null);
});

