test("转移：锁定牌在结算前离开来源时转移失败且没有有效目标、成功日志或协调", async () => {
  const tuner = makePlayer("tuner", 0, "dawn", "ai", 7),
    from = makePlayer("from", 1, "dusk"),
    escaped = makePlayer("escaped", 2, "dusk"),
    ally = makePlayer("ally", 3, "dawn"),
    use = instance("transfer"),
    locked = instance("block");
  tuner.hand.push(use);
  from.hand.push(locked);
  const { game }
    = makeGame([tuner, from, escaped, ally]);
  game.state.deck.cards.push(instance("charge"));
  registerPassiveSkills(game);
  let usedEvent = null;
  game.eventBus.on("beforeCardResolve", "test:remove-locked-transfer-card", () => {
    const index = from.hand.indexOf(locked);
    if (index >= 0) {
      from.hand.splice(index, 1);
      escaped.hand.push(locked);
      from.bumpHandVersion();
      escaped.bumpHandVersion();
    }
  });
  game.eventBus.on("cardUsed", "test:failed-transfer", (event) => {
    usedEvent = event;
  });
  assert.equal(
    await game.playCard(tuner, use, [], { sourceId: from.id, receiverId: ally.id, zone: "hand" }), true
  );
  assert.ok(escaped.hand.includes(locked));
  assert.ok(!ally.hand.includes(locked));
  assert.ok(game.state.deck.discardPile.includes(use));
  assert.ok(!game.state.deck.resolvingCards.includes(use));
  assert.equal(tuner.turnFlags.coordinationTriggered, false);
  assert.equal(tuner.hand.length, 0);
  assert.ok(usedEvent);
  assert.equal(usedEvent.cancelled, true);
  assert.equal(usedEvent.resolved, false);
  assert.deepEqual(usedEvent.effectiveTargets, []);
  assert.equal(
    game.state.logs.some(
      (entry) => entry.message.includes(
        `${tuner.name}将${from.name}的`
      ) && entry.message.includes(`转移给了${ally.name}`)
    ),
    false
  );
});

test("转移：在反制前的日志和响应上下文包含来源与接收者但不泄露隐藏牌名", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk", "human"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), secret = instance("block");
  actor.hand.push(use);
  from.hand.push(secret);
  from.bumpHandVersion();
  const { game, ui }
    = makeGame([actor, from, responder, receiver], { response: () => false });
  const hidden = game.cardSelectionSystem.createHiddenSelection(from);
  await game.playCard(
    actor,
    use,
    [],
    {
      sourceId: from.id,
      receiverId: receiver.id,
      tokens: [hidden.tokens[0].token],
      selectionId: hidden.selectionId
    }
  );
  const request = ui.responseRequests.find(
    (entry) => entry.type === "counter" && entry.targetPlayerId === responder.id
  );
  assert.match(request.presentation.eventText, new RegExp(`${from.name}.*1张牌.*${receiver.name}`));
  assert.doesNotMatch(request.presentation.eventText, new RegExp(secret.name));
  const intentLog = game.state.logs.find((entry) => entry.message.includes("准备将"));
  assert.match(intentLog.message, new RegExp(`${from.name}.*1张牌.*${receiver.name}`));
  assert.doesNotMatch(intentLog.message, new RegExp(secret.name));
});

test("转移：隐藏转移传给 AI 响应策略的公开上下文不含锁定手牌资料", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), secret = { ...instance("block"), name: "绝密锁定牌" };
  actor.hand.push(use);
  from.hand.push(secret);
  responder.hand.push(instance("counter"));
  const { game }
    = makeGame([actor, from, responder, receiver], { random: () => 0 });
  let receivedContext = null;
  game.aiController.responsePolicy.shouldRespond = (_player, _type, context) => {
    receivedContext = context;
    return false;
  };
  await game.playCard(actor, use, [], { sourceId: from.id, receiverId: receiver.id, zone: "hand" });
  assert.ok(receivedContext);
  const publicContext = receivedContext.publicTransferContext;
  assert.ok(publicContext);
  assert.equal(Object.isFrozen(publicContext), true);
  for (
    const forbidden of ["card", "cardId", "definitionId", "hiddenCardName"]
  ) assert.equal(Object.hasOwn(publicContext, forbidden), false);
  const seen = new Set();
  const contains = (value, needle) => {
    if (value === needle) return true;
    if (!value || typeof value !== "object" || seen.has(value)) return false;
    seen.add(value);
    return Object.values(value).some((entry) => contains(entry, needle));
  };
  for (const secretValue of [secret, secret.id, secret.definitionId, secret.name]) {
    seen.clear();
    assert.equal(contains(receivedContext, secretValue), false);
  }
  assert.equal(publicContext.safeItemLabel, "1张牌");
});

test("转移：响应期间手牌换序后仍移动反制前锁定的同一实体", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), locked = instance("block"), other = instance("harvest");
  actor.hand.push(use);
  from.hand.push(locked, other);
  responder.hand.push(instance("counter"));
  const { game }
    = makeGame([actor, from, responder, receiver], { random: () => 0 });
  game.aiController.responsePolicy.shouldRespond = () => {
    from.hand.reverse();
    return false;
  };
  await game.playCard(actor, use, [], { sourceId: from.id, receiverId: receiver.id, zone: "hand" });
  assert.ok(receiver.hand.includes(locked));
  assert.ok(from.hand.includes(other));
  assert.ok(!receiver.hand.includes(other));
});

