test("借势：成功响应使用真实突袭并完整复用次数、伤害、格挡和弃置流程", async () => {
  const actor = makePlayer("actor", 0, "dawn", "human"),
    first = makePlayer("first", 1, "dusk", "human"),
    equipment = instance("battleDevice"),
    assault = instance("assault"),
    blockA = instance("block"),
    blockB = instance("block"),
    use = instance("leverage");
  actor.hand.push(use, blockA, blockB);
  first.hand.push(assault);
  first.equipment = equipment;
  const { game, ui }
    = makeGame(
      [actor, first],
      { response: (request) => request.type === "leverageAssault" || request.type === "block" }
    );
  const hp = actor.hp;
  await game.playCard(
    actor, use, [], { firstTargetId: first.id, equipmentCardId: equipment.id, secondTargetId: actor.id }
  );
  assert.equal(first.equipment, equipment);
  assert.equal(first.turnFlags.attackUsed, 1);
  assert.equal(actor.hp, hp);
  assert.ok(game.state.deck.discardPile.includes(assault));
  assert.ok(game.state.deck.discardPile.includes(use));
  assert.equal(actor.hand.includes(blockA), false);
  assert.equal(actor.hand.includes(blockB), false);
  assert.ok(
    ui.responseRequests.some(
      (request) => request.type === "leverageAssault" && request.legalCardIds.includes(assault.id)
    )
  );
});

test("借势：忽略第一目标已用突袭次数并完整执行真实突袭", async () => {
  const actor = makePlayer("actor", 0, "dawn", "human"),
    first = makePlayer("first", 1, "dusk", "human"),
    equipment = instance("energyDevice"),
    assault = instance("assault"),
    use = instance("leverage");
  actor.hand.push(use);
  first.hand.push(assault);
  first.equipment = equipment;
  const { game, ui }
    = makeGame([actor, first], { response: (request) => request.type === "leverageAssault" });
  first.turnFlags.attackUsed = first.turnFlags.attackLimit;
  assert.equal(RuleEngine.canPlayCard(game, actor, use).ok, true);
  assert.equal(RuleEngine.canUseForcedAssault(game, first, assault, actor).ok, true);
  assert.deepEqual(
    RuleEngine.getUsableAssaultCards(game, first, actor).map((card) => card.id), [assault.id]
  );
  assert.equal(
    await game.playCard(
      actor, use, [], { firstTargetId: first.id, equipmentCardId: equipment.id, secondTargetId: actor.id }
    ),
    true
  );
  assert.ok(
    ui.responseRequests.some(
      (request) => request.type === "leverageAssault" && request.legalCardIds.includes(assault.id)
    )
  );
  assert.equal(first.equipment, equipment);
  assert.equal(first.turnFlags.attackUsed, first.turnFlags.attackLimit + 1);
  assert.ok(game.state.deck.discardPile.includes(assault));
  assert.ok(!actor.hand.includes(equipment));
  assert.ok(!ui.logs.some((message) => message.includes("拒绝使用「突袭」")));
});

