  const messages = game.state.logs.map((entry) => entry.message);
  const declarationIndex = messages.indexOf(`${source.name}对${target.name}使用了「封印」。`);
  const resultIndex = messages.indexOf(`${source.name}使${target.name}进入「封印」状态。`);
