test("反制链：响应牌与装备牌只输出语义日志，不产生底层弃置或通用使用日志", async () => {
  const attacker = makePlayer("attacker", 0, "dawn"),
    defender = makePlayer("defender", 1, "dusk", "human");
  const { game }
    = makeGame([attacker, defender], { response: () => true });
  defender.hand.push(instance("block"));
  await game.damage(
    attacker, defender, 1, { card: instance("assault"), canBlock: true, damageType: "normal" }
  );
  assert.ok(game.state.logs.some((entry) => entry.message === `${defender.name}使用了「格挡」。`));
  assert.ok(!game.state.logs.some((entry) => entry.message.includes("因响应·格挡弃置")));
  const equipment = instance("energyDevice");
  attacker.hand.push(equipment);
  await game.playCard(attacker, equipment, []);
  assert.ok(game.state.logs.some((entry) => entry.message === `${attacker.name}装备了「充能桩」。`));
  assert.ok(!game.state.logs.some((entry) => entry.message.includes("使用了「充能桩」")));
});

test("反制链：真人破坏预选手牌经过双重反制后仍破坏原实体且不泄露私密选择", async () => {
  const source = makePlayer("private-destroy-source", 0, "dawn", "human"),
    target = makePlayer("private-destroy-target", 1, "dusk"),
    third = makePlayer("private-destroy-third", 2, "dawn");
  const use = instance("destroy"),
    secret = {
      ...instance("charge"),
      definitionId: "hidden-destroy-definition",
      name: "隐藏破坏实体标记",
      description: "隐藏破坏描述标记"
    },
    decoy = instance("block"),
    firstCounter = instance("counter"),
    secondCounter = instance("counter");
  source.hand.push(use);
  target.hand.push(secret, decoy, firstCounter);
  third.hand.push(secondCounter);
  const { game, ui }
    = makeGame([source, target, third]), contexts = [];
  forceAvailableAiCounters(game, contexts);
  const selection = await choosePrivateCardThroughInteraction(
    game, source, use, target, { handIndexes: [0] }
  );
  assert.ok(selection?.selectionId);
  assert.ok(game.cardSelectionSystem.selections.size > 0);
  assert.equal(await game.playCard(source, use, [target], selection), true);
  assert.ok(game.state.deck.discardPile.includes(secret));
  assert.ok(target.hand.includes(decoy));
  assert.ok(!target.hand.includes(secret));
  assert.equal(game.cardSelectionSystem.selections.size, 0);
  assert.equal(game.cardSelectionSystem.sessions.size, 0);
  for (const context of contexts) assertNoHiddenSelectionLeak(context, [secret]);
  for (const request of ui.responseRequests) assertNoHiddenSelectionLeak(request, [secret]);
});

