test("濒死：救援阶段保留负生命以计算调息，正式阵亡后归零", async () => {
  const a = makePlayer("a", 0, "dawn"), b = makePlayer("b", 1, "dusk");
  b.hp = 1;
  const { game }
    = makeGame([a, b]);
  let dyingHp = null, need = null;
  game.eventBus.on("playerDying", "test:negative-hp", (event) => {
    dyingHp = event.target.hp;
    need = event.need;
  });
  await game.damage(a, b, 3, { canBlock: false });
  assert.equal(dyingHp, -2);
  assert.equal(need, 3);
  assert.equal(b.hp, 0);
  assert.equal(b.alive, false);
});

