test("AI·模拟器：模拟阵亡会清空手牌装备摘要且评估器只保留死亡惩罚", () => {
  const state = {
    players: [
      {
        id: "killer",
        seatIndex: 0,
        battleTeam: "dawn",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 0
      },
      {
        id: "victim",
        seatIndex: 1,
        battleTeam: "dusk",
        alive: true,
        hp: 1,
        maxHp: 4,
        shield: 0,
        energy: 3,
        handCount: 5,
        hand: [{ id: "a", definitionId: "assault" }],
        expectedAssaultCount: 3,
        expectedRecoverCount: .2,
        assaultResponseProbability: 1,
        blockProbability: 1,
        twoBlockProbability: 1,
        counterProbability: 1,
        equipmentDefinitionId: "battleDevice",
        equipmentRetentionProbability: 1,
        huntMarkSourceId: null,
        huntMarkProbabilities: {}
      }
    ]
  },
    simulator = new AiSimulator(state);
  simulator.applyDamage(state, state.players[0], state.players[1], 1, { canBlock: false });
  const victim = state.players[1];
  assert.deepEqual(
    [
      victim.alive,
      victim.handCount,
      victim.hand.length,
      victim.expectedAssaultCount,
      victim.expectedRecoverCount,
      victim.equipmentDefinitionId,
      victim.equipmentRetentionProbability
    ],
    [false, 0, 0, 0, 0, null, 0]
  );
  const { game }
    = makeGame([makePlayer("viewer", 0, "dawn"), makePlayer("dead", 1, "dusk")]),
    viewer = {
      id: "viewer", battleTeam: "dawn", alive: true, hp: 4, maxHp: 4, shield: 0, energy: 0, handCount: 0
    },
    dead = {
      id: "dead", battleTeam: "dusk", alive: false, hp: 0, maxHp: 4, shield: 0, energy: 0, handCount: 0
    };
  const emptyScore = game.aiController.evaluator.stateUtility({ players: [viewer, dead] }, viewer.id),
    richScore = game.aiController.evaluator.stateUtility(
      {
        players: [
          viewer,
          {
            ...dead,
            shield: 99,
            energy: 99,
            handCount: 99,
            equipmentDefinitionId: "battleDevice",
            equipmentRetentionProbability: 1
          }
        ]
      },
      viewer.id
    );
  assert.equal(richScore, emptyScore);
});

