test("AI·转移：交换敌人未知手牌的真实 definitionId 不改变 AI 转移计划", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    enemy = makePlayer("enemy", 1, "dusk"),
    ally = makePlayer("ally", 2, "dawn");
  const use = instance("transfer"), first = instance("counter"), second = instance("harvest");
  actor.hand.push(use);
  enemy.hand.push(first, second);
  const { game }
    = makeGame([actor, enemy, ally]);
  const choose = () => {
    const action = game.aiController.actionGenerator.generate(
      actor
    ).find((entry) => entry.card?.id === use.id);
    return [action?.selection?.sourceId, action?.selection?.receiverId, action?.selection?.zone];
  };
  const before = choose();
  [first.definitionId, second.definitionId] = [second.definitionId, first.definitionId];
  assert.deepEqual(choose(), before);
});

test("AI·转移：以自己为转移来源时排除正在使用的转移实体", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    ally = makePlayer("ally", 1, "dawn"),
    use = instance("transfer"),
    otherA = instance("harvest"),
    otherB = instance("charge");
  actor.hp = 1;
  actor.hand.push(use, otherA, otherB);
  const { game }
    = makeGame([actor, ally]);
  const action = game.aiController.actionGenerator.generate(
    actor
  ).find((entry) => entry.card?.id === use.id);
  assert.ok(action);
  assert.equal(action.selection.sourceId, actor.id);
  assert.equal(action.selection.zone, "hand");
  const prepared = await game.prepareTransferIntent(actor, use, action.selection);
  assert.ok(prepared);
  assert.notEqual(prepared.privateIntent.card, use);
  assert.ok([otherA, otherB].includes(prepared.privateIntent.card));
});

test("AI·转移：真人以自己为来源时核心拒绝选择正在使用的转移实体", async () => {
  const actor = makePlayer("actor", 0, "dawn", "human"),
    ally = makePlayer("ally", 1, "dawn"),
    use = instance("transfer"),
    other = instance("harvest");
  actor.hand.push(use, other);
  const { game }
    = makeGame([actor, ally]);
  const hidden = game.cardSelectionSystem.createHiddenSelection(actor);
  assert.equal(
    await game.playCard(
      actor,
      use,
      [],
      {
        sourceId: actor.id,
        receiverId: ally.id,
        zone: "hand",
        tokens: [hidden.tokens[0].token],
        selectionId: hidden.selectionId
      }
    ),
    false
  );
  assert.ok(actor.hand.includes(use));
  assert.ok(actor.hand.includes(other));
  assert.ok(!game.state.deck.resolvingCards.includes(use));
  assert.ok(!game.state.deck.discardPile.includes(use));
});

