test("AI·借势：模拟借势不受普通突袭次数槽耗尽影响", () => {
  const basePlayers = (attackUsed) => (
    {
      players: [
        {
          id: "actor",
          seatIndex: 0,
          battleTeam: "dawn",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          handCount: 1,
          hand: [{ id: "l", definitionId: "leverage" }],
          counterProbability: 0,
          expectedEquipmentGain: 0
        },
        {
          id: "first",
          seatIndex: 1,
          battleTeam: "dusk",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          handCount: 2,
          hand: [{ id: "a1", definitionId: "assault" }, { id: "a2", definitionId: "assault" }],
          attackUsed,
          attackLimit: 1,
          attackRange: 1,
          equipmentDefinitionId: "battleDevice",
          equipmentRetentionProbability: 1,
          assaultResponseProbability: 1,
          expectedAssaultCount: 2,
          blockProbability: 0,
          counterProbability: 0
        },
        {
          id: "second",
          seatIndex: 2,
          battleTeam: "dawn",
          alive: true,
          hp: 8,
          maxHp: 8,
          shield: 0,
          handCount: 0,
          blockProbability: 0,
          twoBlockProbability: 0,
          expectedRecoverCount: 0
        }
      ]
    }
  );
  const action = {
    type: "card",
    card: { ...CARD_DEFINITIONS.leverage, id: "l" },
    targets: [{ id: "first" }, { id: "second" }],
    selection: { firstTargetId: "first", secondTargetId: "second" }
  };
  const availableState = basePlayers(0), exhaustedState = basePlayers(1);
  const availableNext = new AiSimulator(availableState).apply(availableState, action, "actor");
  const exhaustedNext = new AiSimulator(exhaustedState).apply(exhaustedState, action, "actor");
  const availableFirst = availableNext.players[1], exhaustedFirst = exhaustedNext.players[1];
  const availableIncrement = availableFirst.attackUsed - 0;
  const exhaustedIncrement = exhaustedFirst.attackUsed - 1;
  assert.ok(availableIncrement > 0);
  assert.ok(exhaustedIncrement > 0);
  assertClose(availableIncrement, exhaustedIncrement);
  assert.ok(exhaustedFirst.attackUsed > exhaustedFirst.attackLimit);
  assertClose(exhaustedFirst.attackUsed, 1 + availableIncrement);
  assertClose(availableNext.players[2].hp, exhaustedNext.players[2].hp);
  assertClose(availableFirst.handCount, exhaustedFirst.handCount);
  assertClose(availableFirst.expectedAssaultCount, exhaustedFirst.expectedAssaultCount);
  assertClose(
    availableFirst.equipmentRetentionProbability, exhaustedFirst.equipmentRetentionProbability
  );
  assertClose(
    availableNext.players[0].expectedEquipmentGain, exhaustedNext.players[0].expectedEquipmentGain
  );
});

