test("AI·雷达：判定聚能可被后续转移给接收者", () => {
  const receiver = radarFixtureTarget(
    {
      id: "receiver",
      battleTeam: "dawn",
      handCount: 0,
      blockCountDistribution: [{ probability: 1, conditions: {}, blockCount: 0 }],
      equipmentDefinitionId: null,
      equipmentRetentionProbability: 0
    }
  );
  const state = {
    remainingCardCounts: { charge: 1 },
    players: [
      radarAttacker(),
      radarFixtureTarget({ blockCountDistribution: [{ probability: 1, conditions: {}, blockCount: 0 }] }),
      receiver
    ]
  };
  const simulator = new AiSimulator({ players: [] });
  simulator.applyDamage(
    state, state.players[0], state.players[1], 1, { canBlock: true, deviceAttack: true }
  );
  const target = state.players[1], charge = target.knownCards[0];
  simulator.transferKnownCardIdentity(
    state,
    target,
    receiver,
    { cardId: charge.cardId, definitionId: "charge" },
    [{ probability: 1, conditions: {}, occurs: true }],
    false
  );
  assert.equal(target.knownCards.length, 0);
  assert.equal(target.handCount, 0);
  assert.equal(receiver.knownCards.length, 1);
  assert.equal(receiver.knownCards[0].definitionId, "charge");
  assert.equal(receiver.handCount, 1);
});

