test("AI·刃行者：模拟按不同类别积累连势且命中的突袭消耗连势", () => {
  const blade = makePlayer("sim-blade", 0, "dawn", "ai", 0),
    enemy = makePlayer("sim-blade-enemy", 1, "dusk"),
    charge = instance("charge"),
    harvest = instance("harvest"),
    assault = instance("assault");
  blade.hand.push(charge, harvest, assault);
  const { game }
    = makeGame([blade, enemy]),
    visible = createAiVisibleState(blade.id, game.state),
    simulator = new AiSimulator(visible);
  const charged = simulator.apply(visible, { type: "card", card: charge, targets: [] }, blade.id);
  const harvested = simulator.apply(charged, { type: "card", card: harvest, targets: [] }, blade.id);
  const attacked = simulator.apply(
    harvested, { type: "card", card: assault, targets: [{ id: enemy.id }] }, blade.id
  );
  assert.deepEqual(charged.players[0].categoriesUsed, ["basic"]);
  assert.equal(charged.players[0].momentum, 1);
  assert.deepEqual(harvested.players[0].categoriesUsed, ["basic", "tactic"]);
  assert.equal(harvested.players[0].momentum, GAME_CONFIG.momentumMaxStacks);
  assert.equal(attacked.players[1].hp, enemy.maxHp - 3);
  assert.equal(attacked.players[0].momentum, 0);
});

