test("AI·赌命者：模拟孤注按E-1摸牌并按25%概率质量合并非叠加状态", () => {
  const makeState = (energy, assaultBonus = 0) => (
    {
      players: [
        {
          id: "gambler",
          battleTeam: "dawn",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy,
          maxEnergy: 4,
          energyBranches: [{ probability: 1, conditions: {}, amount: energy }],
          assaultBonus,
          handCount: 0,
          activeSkillUses: 0,
          activeSkillLimit: 1
        }
      ]
    }
  );
  const action = {
    type: "skill",
    skill: ACTIVE_SKILLS.allIn,
    targets: [],
    executionProbability: 1,
    executionWorldBranches: [{ probability: 1, conditions: {}, executes: true }]
  };
  for (const energy of [1, 2, 3, 4]) {
    const state = makeState(energy),
      next = new AiSimulator(state).apply(state, action, "gambler");
    assertClose(next.players[0].assaultBonus, Math.min(1, energy * .25));
    assertClose(next.players[0].energy, 0);
    assertClose(next.players[0].handCount, energy - 1);
  }
  const fullState = makeState(2, 1),
    partialState = makeState(2, .5),
    full = new AiSimulator(fullState).apply(fullState, action, "gambler"),
    partial = new AiSimulator(partialState).apply(partialState, action, "gambler");
  assertClose(full.players[0].assaultBonus, 1);
  assertClose(full.players[0].energy, 0);
  assertClose(full.players[0].handCount, 1);
  assertClose(partial.players[0].assaultBonus, .75);
  assertClose(partial.players[0].energy, 0);
  assertClose(partial.players[0].handCount, 1);
});

test("AI·赌命者：孤注动作评分按当前状态概率计算边际状态收益", () => {
  const gambler = makePlayer("evaluator-allin", 0, "dawn", "ai", 6),
    enemy = makePlayer("evaluator-allin-enemy", 1, "dusk"),
    { game }
      = makeGame([gambler, enemy]), evaluator = game.aiController.evaluator;
  const makeVisible = (assaultBonus) => (
    { players: [{ id: gambler.id, battleTeam: "dawn", alive: true, energy: 2, assaultBonus }] }
  );
  const action = { type: "skill", skill: ACTIVE_SKILLS.allIn, targets: [] };
  const none = evaluator.actionUtility(action, gambler, makeVisible(0));
  const full = evaluator.actionUtility(action, gambler, makeVisible(1));
  const partial = evaluator.actionUtility(action, gambler, makeVisible(.5));
  assertClose(none, 5);
  assertClose(full, 3);
  assertClose(partial, 4);
  assertClose(none - full, 2);
});

test("AI·赌命者：已有孤注且仅剩1能量时不生成孤注，能量2以上或无状态时仍生成", () => {
  const gambler = makePlayer("ai-allin-filter", 0, "dawn", "ai", 6),
    enemy = makePlayer("ai-allin-filter-enemy", 1, "dusk"),
    { game }
      = makeGame([gambler, enemy]),
    generator = game.aiController.actionGenerator;
  const hasAllIn = (actions) => actions.some(
    (action) => action.type === "skill" && action.skill?.id === "allIn"
  );

  gambler.energy = 1;
  gambler.statuses.allIn = undefined;
  assert.ok(hasAllIn(generator.generate(gambler)), "能量1且无孤注时仍可生成孤注");
  assert.ok(
    hasAllIn(generator.generateFromVisible(createAiVisibleState(gambler.id, game.state), gambler.id)),
    "深层：能量1且无孤注时仍可生成孤注"
  );

  gambler.statuses.allIn = { assaultBonus: 1 };
  assert.ok(!hasAllIn(generator.generate(gambler)), "已有孤注且能量1时不得生成零收益孤注");
  assert.ok(
    !hasAllIn(generator.generateFromVisible(createAiVisibleState(gambler.id, game.state), gambler.id)),
    "深层：assaultBonus已满且能量1时不得生成零收益孤注"
  );

  gambler.energy = 2;
  assert.ok(hasAllIn(generator.generate(gambler)), "已有孤注且能量2时仍可生成孤注摸牌");
  assert.ok(
    hasAllIn(generator.generateFromVisible(createAiVisibleState(gambler.id, game.state), gambler.id)),
    "深层：assaultBonus已满且能量2时仍可生成孤注摸牌"
  );
});

