    enemy = makePlayer("enemy", 2, "dusk");
  a.hp -= 1;
  ally.hp -= 1;
  const { game }
    = makeGame([a, ally, enemy]);
  const use = game.aiController.responsePolicy.shouldRespond(
    a, "counter", { source: enemy, card: instance("symbiosis") }, [instance("counter")]
  );
