test("AI·反制概率：战术反制风险：counterable false 的战术牌结算比例为 1", async () => {
  const actor = makePlayer("a", 0, "dawn"), enemy = makePlayer("e", 1, "dusk");
  const { game }
    = makeGame([actor, enemy]);
  const state = {
    players: [
      makeCounterRiskPlayer("a", "dawn", { seatIndex: 0 }),
      makeCounterRiskPlayer("e", "dusk", { seatIndex: 1, counterProbability: 1 })
    ]
  };
  const simulator = new AiSimulator(state);
  const nonCounterable = {
    category: "tactic", counterable: false, counterScope: "target", aiValue: 5
  };
  assert.equal(simulator.tacticResolutionChance(state, state.players[0], nonCounterable, []), 1);
  assert.equal(
    simulator.targetResolutionChance(state, state.players[0], nonCounterable, state.players[1]), 1
  );
  assert.equal(
    simulator.targetResolutionChance(
      state, state.players[0], { ...nonCounterable, counterScope: "card" }, state.players[1]
    ),
    1
  );
  const visible = { remainingCardCounts: { assault: 30 }, players: state.players };
  const card = { ...nonCounterable, definitionId: "test-no-counter", id: "nc" };
  const action = await planWithStubEvaluator(
    game,
    actor,
    visible,
    [{ type: "card", card, targets: [{ id: "e" }] }, { type: "end" }],
    { actionEconomicValue: (action) => action.type === "end" ? 0 : 0.9, stateUtility: () => 0 }
  );
  assert.equal(action.card?.definitionId, "test-no-counter");
});

test("AI·反制概率：战术反制风险：scout 按反制 scale 记录期望信息收益且不实例化", () => {
  const makeTarget = (overrides) => makeCounterRiskPlayer(
    "t",
    "dusk",
    { seatIndex: 1, handCount: 4, knownCards: [{ cardId: "k1", definitionId: "block" }], ...overrides }
  );
  const run = (target, counterProbability = 0) => {
    const state = { players: [makeCounterRiskPlayer("a", "dawn", { seatIndex: 0 }), target] };
    state.players[1].counterProbability = counterProbability;
    const card = { ...CARD_DEFINITIONS.scout, id: "s" };
    return new AiSimulator(state).apply(state, { type: "card", card, targets: [{ id: "t" }] }, "a");
  };
  const normal = run(makeTarget());
  assert.equal(normal.players[0].expectedInformationGain, 2);
  assert.equal(normal.players[1].knownCards.length, 1);
  assert.equal(Object.hasOwn(normal.players[1], "hand"), false);
  const partial = run(makeTarget(), 0.5);
  // 统一动态反制意愿 = clamp(信息价值/机会成本) ≈ 0.25：反制概率按意愿部分缩放信息收益，
  // 窥探价值低于反制成本，反制无法完全取消收益（旧启发式 desire=1 是高估）。
  assert.ok(partial.players[0].expectedInformationGain < normal.players[0].expectedInformationGain,
    "部分反制概率应降低信息收益");
  const full = run(makeTarget(), 1);
  assert.ok(full.players[0].expectedInformationGain < partial.players[0].expectedInformationGain,
    "反制概率越高信息收益越低");
  const allKnown = run(
    makeTarget(
      {
        handCount: 1,
        knownCards: [{ cardId: "k1", definitionId: "block" }, { cardId: "k2", definitionId: "assault" }]
      }
    )
  );
  assert.equal(allKnown.players[0].expectedInformationGain, 0);
});

test("AI·反制概率：战术反制风险：scout 深层部分可用已知牌按期望数量统计", () => {
  const partialKnown = () => [
    {
      cardId: "k1",
      definitionId: "block",
      availabilityStateBranches: [
        { probability: 0.5, conditions: {}, available: true },
        { probability: 0.5, conditions: {}, available: false }
      ]
    }
  ];
  const run = (counterProbability) => {
    const state = {
      players: [
        makeCounterRiskPlayer("a", "dawn", { seatIndex: 0 }),
        makeCounterRiskPlayer(
          "t", "dusk", { seatIndex: 1, handCount: 2, knownCards: partialKnown(), counterProbability }
        )
      ]
    };
    const card = { ...CARD_DEFINITIONS.scout, id: "s" };
    return new AiSimulator(state).apply(state, { type: "card", card, targets: [{ id: "t" }] }, "a");
  };
  const full = run(0);
  assert.ok(Math.abs(full.players[0].expectedInformationGain - 1.5) < 1e-9);
  assert.equal(full.players[1].knownCards.length, 1);
  const partial = run(0.5);
  // 统一动态反制意愿按 clamp(信息价值/机会成本) 缩放：部分反制概率降低但不归零信息收益。
  assert.ok(partial.players[0].expectedInformationGain < full.players[0].expectedInformationGain,
    "部分反制概率应降低信息收益");
});

test("AI·反制概率：战术反制风险：深层战术评分使用后续节点状态而非根 counter 状态", async () => {
  const actor = makePlayer("a", 0, "dawn"), holder = makePlayer("h", 1, "dusk");
  const { game }
    = makeGame([actor, holder]);
  game.aiRandomnessRange = 0;
  game.aiSearchNodeBudgetOverride = 3;
  const planner = game.aiController.planner;
  planner.evaluator = {
    actionEconomicValue: (action) => {
      if (
        action.type === "end"
      ) return 0.4; if (action.card?.definitionId === "assault") return 1; if (action.card?.definitionId === "harvest") return 1; return 0;
    },
    stateUtility: () => 0
  };
  const visible = {
    remainingCardCounts: { assault: 30 },
    players: [
      makeCounterRiskPlayer("a", "dawn", { seatIndex: 0, attackUsed: 0, attackLimit: 1 }),
      makeCounterRiskPlayer(
        "h",
        "dusk",
        {
          seatIndex: 1,
          hp: 1,
          handCount: 1,
          knownCards: [{ cardId: "hc1", definitionId: "counter" }],
          counterProbability: 1
        }
      )
    ]
  };
  const assaultCard = { ...CARD_DEFINITIONS.assault, id: "hit" };
  const harvestCard = { ...CARD_DEFINITIONS.harvest, id: "draw" };
  let calls = 0;
  game.aiController.actionGenerator.generateFromVisible = (nodeState) => {
    calls += 1;
    return calls === 1 ? [{ type: "card", card: harvestCard, targets: [] }, { type: "end" }] : [];
  };
  const action = await planner.plan(
    actor,
    visible,
    [{ type: "card", card: assaultCard, targets: [{ id: "h" }] }],
    { gameId: game.state.gameId }
  );
  assert.equal(action.card?.definitionId, "assault");
  assert.deepEqual(planner.lastPlannedSequence.map((entry) => entry.cardId), ["assault", "harvest"]);
});

test("AI·反制概率：战术反制风险：assault 隐藏格挡调整保持原行为", async () => {
  const actor = makePlayer("a", 0, "dawn"), target = makePlayer("t", 1, "dusk");
  const run = async (knownBlock) => {
    const { game }
      = makeGame([actor, target]);
    game.aiRandomnessRange = 0;
    game.aiSearchNodeBudgetOverride = 2;
    const planner = game.aiController.planner;
    planner.evaluator = {
      actionUtility: (action) => action.type === "end" ? 0.4 : 1, stateUtility: () => 0
    };
    game.aiController.actionGenerator.generateFromVisible = () => [];
    const visible = {
      remainingCardCounts: { assault: 30 },
      players: [
        makeCounterRiskPlayer("a", "dawn", { seatIndex: 0, attackUsed: 0, attackLimit: 1 }),
        makeCounterRiskPlayer(
          "t",
          "dusk",
          {
            seatIndex: 1,
            handCount: knownBlock ? 1 : 0,
            knownCards: knownBlock ? [{ cardId: "b1", definitionId: "block" }] : []
          }
        )
      ]
    };
    const assault = { ...CARD_DEFINITIONS.assault, id: "hit" };
    const result = await planner.plan(
      actor,
      visible,
      [{ type: "card", card: assault, targets: [{ id: "t" }] }, { type: "end" }],
      { gameId: game.state.gameId }
    );
    return {
      action: result,
      expanded: planner.lastSearchStats?.expanded,
      sequence: planner.lastPlannedSequence?.map((entry) => entry.cardId)
    };
  };
  const withBlock = await run(true), withoutBlock = await run(false);
  assert.equal(withBlock.action.type, "end");
  assert.equal(withoutBlock.action.card?.definitionId, "assault");
});

