test("AI·反制概率：确定反制转移后来源减一接收者加一", () => {
  const source = counterPlayer(
    "s", "dusk", { handCount: 1, counterProbability: 1, knownCards: [counterKnownCard("c1")] }
  );
  const receiver = counterPlayer("r", "dawn", { handCount: 0, counterProbability: 0 });
  const state = { players: [counterPlayer("a", "dawn"), source, receiver] };
  const simulator = new AiSimulator({ players: [] });
  simulator.transferKnownCardIdentity(
    state,
    source,
    receiver,
    { cardId: "c1", definitionId: "counter" },
    [{ probability: 1, conditions: {}, occurs: true }],
    false
  );
  assert.equal(source.knownCards.length, 0);
  assert.equal(counterProbabilityOf(source), 0);
  assert.equal(source.handCount, 0);
  assert.equal(receiver.knownCards.length, 1);
  assert.equal(counterProbabilityOf(receiver), 1);
  assert.equal(receiver.handCount, 1);
});

test("AI·反制概率：匿名反制转移容量守恒且共享条件世界", () => {
  const source = counterPlayer(
    "s",
    "dusk",
    { handCount: 1, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 1 }] }
  );
  const receiver = counterPlayer(
    "r",
    "dawn",
    { handCount: 0, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }] }
  );
  const state = { players: [counterPlayer("a", "dawn"), source, receiver] };
  const simulator = new AiSimulator({ players: [] });
  simulator.transferUnknownCardIdentity(
    state, source, receiver, [{ probability: 1, conditions: {}, occurs: true }], 1
  );
  assert.equal(counterProbabilityOf(source), 0);
  assert.equal(source.handCount, 0);
  assert.equal(counterProbabilityOf(receiver), 1);
  assert.equal(receiver.handCount, 1);
  const joint = joinProbabilityStateBranches(
    source.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, sourceCount: counterCount }
      )
    ),
    receiver.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, receiverCount: counterCount }
      )
    )
  );
  const both = joint.filter(
    (branch) => branch.sourceCount === 0 && branch.receiverCount === 1
  ).reduce((sum, branch) => sum + branch.probability, 0);
  assertClose(both, 1);
});

test("AI·反制概率：整手牌随机移除互斥消费已知或匿名反制", () => {
  const player = counterPlayer(
    "t",
    "dusk",
    {
      handCount: 2,
      knownCards: [counterKnownCard("k1")],
      counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 1 }]
    }
  );
  const simulator = new AiSimulator({ players: [] });
  simulator.consumeRandomHandCards({ players: [player] }, player, 1);
  assertClose(simulator.cardAvailability(player.knownCards[0]), .5);
  const byCount = counterByCount(player);
  assertClose(byCount[0] ?? 0, .5);
  assertClose(byCount[1] ?? 0, .5);
  const joint = joinProbabilityStateBranches(
    projectAvailability(player.knownCards[0].availabilityStateBranches, "keptAvail"),
    player.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, count1: counterCount === 1 }
      )
    )
  );
  const impossible = joint.filter(
    (branch) => branch.keptAvail && !branch.count1
  ).reduce((sum, branch) => sum + branch.probability, 0);
  assert.ok(Math.abs(impossible) < 1e-9);
});

test("AI·反制概率：新摸一张匿名牌只增加该新牌反制先验且旧牌不复活", () => {
  const player = counterPlayer(
    "t",
    "dusk",
    { handCount: 1, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }] }
  );
  const state = { remainingCardCounts: { counter: 10 }, players: [player] };
  const simulator = new AiSimulator({ players: [] });
  const gainWorlds = [{ probability: 1, conditions: { draw: "yes" }, occurs: true }];
  player.handCount += 1;
  simulator.addOneUnknownCardToCounterDistribution(state, player, gainWorlds);
  assert.equal(player.counterProbability, 1);
  const byCount = counterByCount(player);
  assertClose(byCount[0] ?? 0, 0);
  assertClose(byCount[1] ?? 0, 1);
  // 旧匿名反制消费后摸新牌：新牌才有先验，旧牌不恢复。
  const consumed = counterPlayer(
    "u",
    "dusk",
    { handCount: 0, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }] }
  );
  const state2 = { remainingCardCounts: { counter: 10 }, players: [consumed] };
  consumed.handCount = 1;
  simulator.addOneUnknownCardToCounterDistribution(state2, consumed, gainWorlds);
  assert.equal(consumed.counterProbability, 1);
  assert.ok(consumed.counterCountDistribution.every((branch) => branch.conditions.draw === "yes"));
});

