test("AI·反制容量：唯一匿名50%反制窃取后与来源同条件世界", () => {
  const actor = counterPlayer(
    "a",
    "dawn",
    { handCount: 0, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }] }
  );
  const target = counterPlayer(
    "t",
    "dusk",
    {
      handCount: 1,
      counterCountDistribution: [
        { probability: .5, conditions: { anon: "no" }, counterCount: 0 },
        { probability: .5, conditions: { anon: "yes" }, counterCount: 1 }
      ]
    }
  );
  const state = { players: [actor, target] };
  const simulator = new AiSimulator(state);
  simulator.stealResourceToHand(state, actor, target, 1);
  assert.equal(target.handCount, 0);
  assert.equal(counterProbabilityOf(target), 0);
  const byCount = counterByCount(actor);
  assertClose(byCount[0] ?? 0, .5);
  assertClose(byCount[1] ?? 0, .5);
  assertClose(actor.counterProbability, .5);
  const count1Branches = actor.counterCountDistribution.filter((branch) => branch.counterCount === 1);
  assert.ok(count1Branches.some((branch) => branch.conditions.anon === "yes"));
  const count0Branches = actor.counterCountDistribution.filter((branch) => branch.counterCount === 0);
  assert.ok(count0Branches.some((branch) => branch.conditions.anon === "no"));
});

test("AI·反制容量：手牌与装备各有概率时只转移手牌世界反制", () => {
  const actor = counterPlayer(
    "a",
    "dawn",
    { handCount: 0, counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 0 }] }
  );
  const target = counterPlayer(
    "t",
    "dusk",
    {
      handCount: 1,
      counterCountDistribution: [{ probability: 1, conditions: {}, counterCount: 1 }],
      equipmentDefinitionId: "energyDevice",
      equipmentRetentionProbability: 1
    }
  );
  const state = { players: [actor, target] };
  const simulator = new AiSimulator(state);
  simulator.stealResourceToHand(state, actor, target, 1);
  assert.equal(actor.handCount, 1);
  assertClose(actor.counterProbability, .5);
  assertClose(target.equipmentRetentionProbability, .5);
  assertClose(target.handCount, .5);
  assertClose(counterProbabilityOf(target), .5);
  const joint = joinProbabilityStateBranches(
    actor.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, actorCount1: counterCount === 1 }
      )
    ),
    target.counterCountDistribution.map(
      ({ probability, conditions, counterCount }) => (
        { probability, conditions, targetCount1: counterCount === 1 }
      )
    )
  );
  const both = joint.filter(
    (branch) => branch.actorCount1 && branch.targetCount1
  ).reduce((sum, branch) => sum + branch.probability, 0);
  assert.ok(Math.abs(both) < 1e-9);
});

