// ---- AI 隐藏信息与牌身份 ----

const fullKnownCard = (cardId, definitionId) => (
  {
    cardId,
    definitionId,
    availabilityBranches: [{ probability: 1, conditions: {} }],
    availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
  }
);

const fullHandCard = (id, definitionId) => (
  {
    id,
    definitionId,
    availabilityBranches: [{ probability: 1, conditions: {} }],
    availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
  }
);

const blockDistributionByCount = (distribution) => {
  const byCount = {};
  for (const branch of distribution) {
    byCount[branch.blockCount] = (byCount[branch.blockCount] ?? 0) + branch.probability;
  }
  return byCount;
};

const projectAvailability = (branches, field) => branches.map(
  ({ available, probability, conditions }) => (
    { probability, conditions, [field]: Boolean(available) }
  )
);

test("AI·资源身份：部分概率转移中来源与接收者身份世界互补", () => {
  const state = {
    playPhaseEnded: false,
    remainingCardCounts: { assault: 10 },
    players: [
      {
        id: "z-actor",
        seatIndex: 0,
        battleTeam: "dawn",
        generalId: "blade-walker",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 1,
        hand: [{ id: "move", definitionId: "transfer" }],
        equipmentDefinitionId: "telescope",
        equipmentRetentionProbability: .4,
        counterProbability: 0,
        attackRange: 1
      },
      {
        id: "near",
        seatIndex: 1,
        battleTeam: "dusk",
        alive: true,
        hp: 4,
        maxHp: 4,
        handCount: 0,
        counterProbability: 0
      },
      {
        id: "source",
        seatIndex: 2,
        battleTeam: "dusk",
        generalId: "oath-warden",
        alive: true,
        hp: 4,
        maxHp: 4,
        handCount: 1,
        knownCards: [
          {
            cardId: "known-assault",
            definitionId: "assault",
            availabilityBranches: [{ probability: 1, conditions: {} }],
            availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
          }
        ],
        counterProbability: 0
      },
      {
        id: "a-receiver",
        seatIndex: 3,
        battleTeam: "dawn",
        generalId: "spirit-medic",
        alive: true,
        hp: 4,
        maxHp: 4,
        handCount: 0,
        counterProbability: 0
      },
      {
        id: "tail",
        seatIndex: 4,
        battleTeam: "dusk",
        alive: true,
        hp: 4,
        maxHp: 4,
        handCount: 0,
        counterProbability: 0
      }
    ]
  };
  const { game }
    = makeGame([makePlayer("real", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const action = game.aiController.actionGenerator.generateFromVisible(
    state, "z-actor"
  ).find((entry) => entry.card?.id === "move");
  assert.ok(action);
  assertClose(action.executionProbability, .4);
  const next = new AiSimulator(state).apply(state, action, "z-actor");
  const nextActor = next.players[0], nextSource = next.players[2];
  const sourceEntry = nextSource.knownCards.find((entry) => entry.cardId === "known-assault");
  const receiverEntry = nextActor.hand.find((card) => card.id === "known-assault");
  assert.ok(sourceEntry);
  assert.ok(receiverEntry);
  const sourceAvailable = sourceEntry.availabilityStateBranches.reduce(
    (sum, branch) => sum + (branch.available ? branch.probability : 0), 0
  );
  const receiverAvailable = receiverEntry.availabilityStateBranches.reduce(
    (sum, branch) => sum + (branch.available ? branch.probability : 0), 0
  );
  assertClose(sourceAvailable, .6);
  assertClose(receiverAvailable, .4);
  assertClose(sourceAvailable + receiverAvailable, 1);
  const joined = joinProbabilityStateBranches(
    sourceEntry.availabilityStateBranches.map(
      (branch) => (
        {
          probability: branch.probability, conditions: branch.conditions, sourceAvailable: branch.available
        }
      )
    ),
    receiverEntry.availabilityStateBranches.map(
      (branch) => (
        {
          probability: branch.probability, conditions: branch.conditions, receiverAvailable: branch.available
        }
      )
    )
  );
  assert.ok(joined.length > 0);
  for (const branch of joined) {
    assert.equal(branch.sourceAvailable || branch.receiverAvailable, true);
    assert.equal(branch.sourceAvailable && branch.receiverAvailable, false);
  }
  assertClose(nextSource.handCount, .6);
  assertClose(1 - nextSource.handCount, receiverAvailable);
});

