test("AI·资源身份：部分概率高价值牌不再按完整确定身份评分", () => {
  const actor = { id: "actor", battleTeam: "dawn" };
  const receiver = { id: "receiver", battleTeam: "dawn", generalId: "spirit-medic", hp: 4, maxHp: 4 };
  const makeFrom = (cards, handCount) => (
    {
      id: "from",
      battleTeam: "dusk",
      generalId: "blade-walker",
      hp: 4,
      maxHp: 4,
      handCount,
      knownCards: cards
    }
  );
  const partialCard = {
    cardId: "high-20",
    definitionId: "counter",
    availabilityStateBranches: [
      { probability: .2, conditions: {}, available: true },
      { probability: .8, conditions: {}, available: false }
    ]
  };
  const partial = chooseTransferHandCandidate(actor, makeFrom([partialCard], .2), receiver);
  assert.equal(partial.selectionKind, "unknown");
  assert.equal(partial.cardId, null);
  assertClose(partial.availableUnknownCount, .2);
  const partialScore = scoreTransferCombination(
    { actor, from: makeFrom([partialCard], .2), receiver, zone: "hand" }
  );
  const fullScore = scoreTransferCombination(
    {
      actor,
      from: makeFrom(
        [
          {
            cardId: "high-full",
            definitionId: "counter",
            availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
          }
        ],
        1
      ),
      receiver,
      zone: "hand"
    }
  );
  assert.ok(partialScore < fullScore);
});

