test("AI·资源身份：已知转移同步来源与接收者四类摘要", () => {
  const scenarios = [
    ["recover", "expectedRecoverCount"],
    ["block", "blockProbability"],
    ["counter", "counterProbability"],
    ["assault", "expectedAssaultCount"]
  ];
  for (const [definitionId, field] of scenarios) {
    const state = {
      playPhaseEnded: false,
      remainingCardCounts: { [definitionId]: 10 },
      players: [
        {
          id: "a",
          seatIndex: 0,
          battleTeam: "dawn",
          generalId: "blade-walker",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          hand: [{ id: "use", definitionId: "transfer" }],
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        },
        {
          id: "s",
          seatIndex: 1,
          battleTeam: "dusk",
          generalId: "oath-warden",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          knownCards: [
            {
              cardId: `k-${definitionId}`,
              definitionId,
              availabilityBranches: [{ probability: 1, conditions: {} }],
              availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
            }
          ],
          counterProbability: 0
        },
        {
          id: "r",
          seatIndex: 2,
          battleTeam: "dawn",
          generalId: "spirit-medic",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 0,
          counterProbability: 0
        }
      ]
    };
    const transferCard = state.players[0].hand[0];
    const action = {
      type: "card",
      card: transferCard,
      targets: [],
      selection: {
        sourceId: "s",
        receiverId: "r",
        zone: "hand",
        score: 10,
        selectionKind: "known",
        cardId: `k-${definitionId}`,
        definitionId,
        expectedValue: 1,
        availableUnknownCount: 0
      }
    };
    const next = new AiSimulator(state).apply(state, action, "a");
    const nextSource = next.players[1], nextReceiver = next.players[2];
    assert.equal(nextSource[field], 0, `${definitionId} source`);
    assert.equal(nextReceiver[field], 1, `${definitionId} receiver`);
    if (definitionId === "block") {
      assert.equal(nextSource.twoBlockProbability, 0);
      assert.equal(nextReceiver.twoBlockProbability, 0);
    }
    if (definitionId === "assault") {
      assert.equal(nextSource.assaultResponseProbability, 0);
      assert.equal(nextReceiver.assaultResponseProbability, 1);
    }
  }
});

test("AI·资源身份：模拟执行评分阶段选中的同一已知牌身份", () => {
  const state = {
    playPhaseEnded: false,
    remainingCardCounts: { counter: 10 },
    players: [
      {
        id: "a",
        seatIndex: 0,
        battleTeam: "dawn",
        generalId: "blade-walker",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 1,
        hand: [{ id: "use", definitionId: "transfer" }],
        attackRange: 1,
        equipmentDefinitionId: null,
        equipmentRetentionProbability: 0,
        counterProbability: 0
      },
      {
        id: "s",
        seatIndex: 1,
        battleTeam: "dusk",
        generalId: "oath-warden",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 2,
        knownCards: [
          {
            cardId: "low-charge",
            definitionId: "charge",
            availabilityBranches: [{ probability: 1, conditions: {} }],
            availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
          },
          {
            cardId: "high-counter",
            definitionId: "counter",
            availabilityBranches: [{ probability: 1, conditions: {} }],
            availabilityStateBranches: [{ probability: 1, conditions: {}, available: true }]
          }
        ],
        counterProbability: 0
      },
      {
        id: "r",
        seatIndex: 2,
        battleTeam: "dawn",
        generalId: "spirit-medic",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        handCount: 0,
        counterProbability: 0
      }
    ]
  };
  const { game }
    = makeGame([makePlayer("real", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const action = game.aiController.actionGenerator.generateFromVisible(
    state, "a"
  ).find((entry) => entry.card?.definitionId === "transfer");
  assert.ok(action);
  assert.equal(action.selection.cardId, "high-counter");
  const simulator = new AiSimulator(state), next = simulator.apply(state, action, "a");
  const nextSource = next.players[1], nextReceiver = next.players[2];
  // 来源持有确定反制，统一动态反制意愿 = clamp(转移价值/机会成本) = 11/14 →
  // 3/14 世界转移成功、11/14 世界来源保留该反制并消费容量。
  assertClose(nextSource.handCount, 25 / 14);
  assertClose(nextReceiver.handCount, 3 / 14);
  const sourceHigh = nextSource.knownCards.find((entry) => entry.cardId === "high-counter");
  assert.ok(sourceHigh);
  assertClose(simulator.cardAvailability(sourceHigh), 11 / 14);
  const receiverHigh = nextReceiver.knownCards.find((entry) => entry.cardId === "high-counter");
  assert.ok(receiverHigh);
  assertClose(simulator.cardAvailability(receiverHigh), 3 / 14);
  assert.ok(!nextReceiver.knownCards.some((entry) => entry.cardId === "low-charge"));
  assert.ok(nextSource.knownCards.some((entry) => entry.cardId === "low-charge"));
});

