test("AI·角色选牌：弃牌原有动态修正全部保留", () => {
  const enemy = makePlayer("enemy", 1, "dusk");
  const recover = instance("recover"), shield = instance("shield");
  // 满血 recover -2：刃行者 recover 6→4、shield 7 → 弃 recover
  const fullHp = makePlayer("full", 0, "dawn");
  const { game: fullGame }
    = makeGame([fullHp, enemy], { random: () => 0 });
  fullHp.hand = [recover, shield];
  assert.deepEqual(
    fullGame.aiController.chooseDiscards(fullHp, 1).map((card) => card.definitionId), ["recover"]
  );
  // 濒死 recover +7 与 block +6：弃 charge/assault 而保留 recover/block
  const lowHp = makePlayer("low", 0, "dawn");
  const { game: lowGame }
    = makeGame([lowHp, enemy], { random: () => 0 });
  lowHp.hp = 1;
  const block = instance("block"), charge = instance("charge"), assault = instance("assault");
  lowHp.hand = [recover, block, charge, assault];
  const lowDiscarded = lowGame.aiController.chooseDiscards(lowHp, 2).map((card) => card.definitionId);
  assert.ok(!lowDiscarded.includes("recover") && !lowDiscarded.includes("block"));
  // symbiosis -5：刃行者 symbiosis 4-5=-1 → 优先弃置
  const symbiosis = instance("symbiosis");
  const gambler = makePlayer("gambler", 0, "dawn");
  const { game: symbiosisGame }
    = makeGame([gambler, enemy], { random: () => 0 });
  gambler.hand = [assault, symbiosis];
  assert.deepEqual(
    symbiosisGame.aiController.chooseDiscards(gambler, 1).map((card) => card.definitionId),
    ["symbiosis"]
  );
  // stranded assault +5：无距离1敌人时 assault 6+5=11 > scout 4 → 弃 scout
  const stranded = makePlayer("stranded", 0, "dawn");
  const ally = makePlayer("ally", 1, "dawn");
  const farEnemy = makePlayer("far", 2, "dusk");
  const tailA = makePlayer("tail-a", 3, "dawn");
  const tailB = makePlayer("tail-b", 4, "dawn");
  const { game: strandedGame }
    = makeGame([stranded, ally, farEnemy, tailA, tailB], { random: () => 0 });
  const scout = instance("scout");
  stranded.hand = [assault, scout];
  assert.deepEqual(
    strandedGame.aiController.chooseDiscards(stranded, 1).map((card) => card.definitionId), ["scout"]
  );
});

test("AI·角色选牌：低血已装备时保留反制并弃冗余充能桩", () => {
  const actor = makePlayer("actor", 0, "dawn", "ai", 4); // 炎术师：counter 7、energyDevice 8
  const enemy = makePlayer("enemy", 1, "dusk");
  const { game }
    = makeGame([actor, enemy], { random: () => 0 });
  actor.hp = 1;
  const counter = instance("counter"), energyDevice = instance("energyDevice");
  // 同款冗余：已装备充能桩时，手中充能桩只按替换净增量计值
  actor.equipment = instance("energyDevice");
  actor.hand = [energyDevice, counter];
  assert.deepEqual(
    game.aiController.chooseDiscards(actor, 1).map((card) => card.definitionId), ["energyDevice"]
  );
  assert.deepEqual(actor.hand.map((card) => card.definitionId), ["energyDevice", "counter"]);
  // 不同装备：已装备雷达时，充能桩的边际保留价值仍低于反制
  actor.equipment = instance("defenseDevice");
  actor.hand = [instance("energyDevice"), instance("counter")];
  assert.deepEqual(
    game.aiController.chooseDiscards(actor, 1).map((card) => card.definitionId), ["energyDevice"]
  );
});

