test("生命周期：旧局公共池、目标和弃牌等待取消后不移动实体且不影响新 UI", async () => {
  for (const mode of ["public", "target", "discard"]) {
    const ui = makeOwnedUi(),
      human = makePlayer(`old-${mode}-human`, 0, "dawn", "human"),
      enemy = makePlayer(`old-${mode}-enemy`, 1, "dusk");
    const old = configureOwnedGame(new Game(ui), [human, enemy]);
    ui.attachGame(old);
    let openedResolve;
    const opened = new Promise((resolve) => {
      openedResolve = resolve;
    });
    let pending, tracked;
    if (mode === "public") {
      ui.onResponse = () => {
        const state = ui.responseState;
        ui.responseState = null;
        state.resolve({ status: "declined" });
      };
      ui.onPublic = openedResolve;
      old.state.deck.cards.push(instance("block"), instance("charge"));
      tracked = instance("mutualBenefit");
      human.hand.push(tracked);
      pending = old.playCard(human, tracked, []);
    } else if (mode === "target") {
      ui.onTarget = openedResolve;
      tracked = instance("assault");
      human.hand.push(tracked);
      pending = old.handleHumanCard(tracked.id);
    } else {
      ui.onDiscard = openedResolve;
      tracked = instance("block");
      human.hand.push(tracked, instance("charge"));
      human.hp = 1;
      old.state.phase = "discard";
      pending = old.handleDiscardPhase(human, old.state.gameId);
    }
    await opened;
    old.dispose();
    const fresh = configureOwnedGame(
      new Game(ui),
      [makePlayer(`new-${mode}-human`, 0, "dawn", "human"), makePlayer(`new-${mode}-enemy`, 1, "dusk")]
    );
    ui.attachGame(fresh);
    ui.renders = [];
    ui.mutations = [];
    ui.logs = [];
    await pending;
    assert.equal(ui.game, fresh);
    assert.deepEqual(ui.renders, []);
    assert.deepEqual(ui.mutations, []);
    assert.deepEqual(ui.logs, []);
    assert.ok(!human.hand.includes(undefined));
    if (mode !== "public") assert.ok(human.hand.includes(tracked));
  }
});

