test("集成：全 AI 快速对局能推进到合法胜者", async () => {
  let seed = 77;
  const random = () => ((seed = Math.imul(seed, 1664525) + 1013904223 >>> 0) / 4294967296);
  const ui = makeUi();
  const game = new Game(ui, random);
  game.simulationMode = true;
  game.setAnimationFastMode(true);
  game.cleanupManager.delay = async () => !game.state.isDisposed;
  const candidates = game.startSelection();
  game.state.players[0].controllerType = "ai";
  await game.confirmGeneral(candidates[0].id);
  const result = await Promise.race(
    [
      game.loopPromise.then(() => "done"),
      new Promise((resolve) => setTimeout(() => resolve("timeout"), 10000))
    ]
  );
  assert.equal(result, "done");
  assert.ok(["dawn", "dusk"].includes(game.state.winnerTeam));
  game.dispose();
});

test("集成：掠夺装备收入手牌且不会替换或弃置使用者旧装备", async () => {
  const actor = makePlayer("actor", 0, "dawn", "human"),
    target = makePlayer("target", 1, "dusk"),
    use = instance("plunder");
  const old = instance("barrierDevice"), moved = instance("energyDevice");
  actor.equipment = old;
  actor.hand.push(use);
  target.equipment = moved;
  const { game }
    = makeGame([actor, target]);
  const selection = game.cardSelectionSystem.createHiddenSelection(target);
  await game.playCard(
    actor,
    use,
    [target],
    { zone: "equipment", equipmentCardId: moved.id, selectionId: selection.selectionId }
  );
  assert.equal(actor.equipment, old);
  assert.ok(actor.hand.includes(moved));
  assert.ok(!game.state.deck.discardPile.includes(old));
  assert.equal(target.equipment, null);
  assert.equal(await game.playCard(actor, moved, []), true);
  assert.equal(actor.equipment, moved);
  assert.ok(game.state.deck.discardPile.includes(old));
});

