test("集成：击杀奖励配置为1且 AI 模拟使用同一奖励数量", () => {
  const killer = makePlayer("sim-killer", 0, "dawn"),
    target = makePlayer("sim-victim", 1, "dusk"),
    assault = instance("assault");
  killer.hand.push(assault);
  target.hp = 1;
  target.statuses = {
    exposeWeakness: { stacks: 2 }, huntMark: { sourceId: "hunter" }, allIn: { assaultBonus: 1 }
  };
  target.turnFlags.momentum = 2;
  const { game }
    = makeGame([killer, target]),
    visible = createAiVisibleState(killer.id, game.state),
    next = new AiSimulator(
      visible
    ).apply(visible, { type: "card", card: assault, targets: [{ id: target.id }] }, killer.id);
  const simulatedTarget = next.players.find((player) => player.id === target.id);
  assert.equal(GAME_CONFIG.killRewardDrawCount, 1);
  assert.equal(simulatedTarget.alive, false);
  assert.equal(next.players.find((player) => player.id === killer.id).handCount, 1);
  assert.deepEqual(
    [
      simulatedTarget.exposeWeaknessStacks,
      simulatedTarget.assaultBonus,
      simulatedTarget.huntMarkSourceId,
      simulatedTarget.momentum,
      simulatedTarget.statuses
    ],
    [0, 0, null, 0, []]
  );
});

test("集成：正式阵亡会在首次界面刷新前清空状态和连势", async () => {
  const source = makePlayer("death-source", 0, "dawn"),
    target = makePlayer("death-target", 1, "dusk"),
    survivor = makePlayer("death-survivor", 2, "dusk"),
    { game, ui }
      = makeGame([source, target, survivor]);
  target.hp = 0;
  target.statuses = {
    exposeWeakness: { stacks: 2 }, huntMark: { sourceId: source.id }, allIn: { assaultBonus: 1 }
  };
  target.turnFlags.momentum = 3;
  const snapshots = [];
  const originalRender = ui.render.bind(ui);
  ui.render = (renderedGame) => {
    snapshots.push(
      { statuses: { ...target.statuses }, momentum: target.turnFlags.momentum, alive: target.alive }
    );
    return originalRender(renderedGame);
  };
  assert.equal(await game.dyingSystem.kill(target, source), true);
  assert.deepEqual(target.statuses, {});
  assert.equal(target.turnFlags.momentum, 0);
  assert.equal(target.alive, false);
  assert.deepEqual(snapshots[0], { statuses: {}, momentum: 0, alive: false });
});

test("集成：无明确来源的死亡不奖励且连续击杀两个敌人各奖励1张", async () => {
  const current = makePlayer("no-source-current", 0, "dawn"),
    victim = makePlayer("no-source-victim", 1, "dusk"),
    other = makePlayer("no-source-other", 2, "dusk");
  victim.hp = 0;
  const noSource = makeGame([current, victim, other]);
  noSource.game.state.deck.cards.push(instance("charge"));
  await noSource.game.dyingSystem.kill(victim, null);
  assert.equal(current.hand.length, 0);
  const killer = makePlayer("double-killer", 0, "dawn"),
    ally = makePlayer("double-ally", 1, "dawn"),
    enemyA = makePlayer("double-enemy-a", 2, "dusk"),
    enemyB = makePlayer("double-enemy-b", 3, "dusk");
  enemyA.hp = 1;
  enemyB.hp = 1;
  const fixture = makeGame([killer, ally, enemyA, enemyB]);
  fixture.game.state.deck.cards.push(instance("charge"), instance("block"));
  let rewards = 0;
  fixture.game.eventBus.on("enemyKilled", "test:count-kill-reward", () => {
    rewards += 1;
  });
  await fixture.game.damage(killer, enemyA, 1, { canBlock: false });
  await fixture.game.damage(killer, enemyB, 1, { canBlock: false });
  assert.equal(killer.hand.length, 2);
  assert.equal(rewards, 2);
  assert.equal(await fixture.game.dyingSystem.kill(enemyB, killer), false);
  assert.equal(killer.hand.length, 2);
});

